package com.example.fileservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}

fun Application.configureRouting() {
    routing {
        // Health check endpoint
        get("/health") {
            call.respondText("OK", ContentType.Text.Plain)
        }

        // File listing for user workspace
        get("/workspace/list") {
            val subdir = call.request.queryParameters["path"] ?: "."
            val baseDir = System.getenv("WORKSPACE_ROOT") ?: "/srv/workspace"
            val targetPath = File(baseDir, subdir).canonicalPath

            // Basic path traversal check
            if (!targetPath.startsWith(baseDir)) {
                call.respond(HttpStatusCode.Forbidden, "Access denied")
                return@get
            }

            val dir = File(targetPath)
            if (dir.exists() && dir.isDirectory) {
                val files = dir.listFiles()?.map { it.name } ?: emptyList()
                call.respondText(files.joinToString("\n"), ContentType.Text.Plain)
            } else {
                call.respond(HttpStatusCode.NotFound, "Directory not found")
            }
        }

        // Diagnostic endpoint - runs system commands for monitoring
        post("/admin/diagnostic") {
            val authHeader = call.request.headers["X-Admin-Token"]
            val expectedToken = System.getenv("ADMIN_TOKEN") ?: "changeme"

            if (authHeader != expectedToken) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid token")
                return@post
            }

            val body = call.receiveText()
            val command = body.trim()

            // Allowlist of diagnostic commands
            val allowedPrefixes = listOf("df", "free", "uptime", "ps", "cat /proc")
            val isAllowed = allowedPrefixes.any { command.startsWith(it) }

            if (!isAllowed) {
                call.respond(HttpStatusCode.Forbidden, "Command not in allowlist")
                return@post
            }

            try {
                val process = Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", command))
                val reader = BufferedReader(InputStreamReader(process.inputStream))
                val output = reader.readText()
                val exitCode = process.waitFor()

                call.respondText(
                    "Exit: $exitCode\n---\n$output",
                    ContentType.Text.Plain
                )
            } catch (e: Exception) {
                call.respond(
                    HttpStatusCode.InternalServerError,
                    "Error: ${e.message}"
                )
            }
        }

        // File read endpoint for workspace files
        get("/workspace/read") {
            val filePath = call.request.queryParameters["file"] ?: ""
            val baseDir = System.getenv("WORKSPACE_ROOT") ?: "/srv/workspace"
            val target = File(baseDir, filePath)

            if (!target.canonicalPath.startsWith(baseDir)) {
                call.respond(HttpStatusCode.Forbidden, "Access denied")
                return@get
            }

            if (target.exists() && target.isFile) {
                call.respondFile(target)
            } else {
                call.respond(HttpStatusCode.NotFound, "File not found")
            }
        }
    }
}

// Utility: validate workspace paths don't escape
fun isPathSafe(base: String, requested: String): Boolean {
    val canonical = File(base, requested).canonicalPath
    return canonical.startsWith(File(base).canonicalPath)
}
